      "planEdits": {
        "item_3": {
          "causa": "Escalera de acceso a archivo en subsuelo carece de pasamanos, alzada mayor a 0,18 m y bandas antideslizantes incompletas (Foto 9)",
          "que": "Instalar pasamanos reglamentario y colocar bandas antideslizantes en el ancho total de peldaños",
          "como": "Amurar pasamanos continuo metálico a 0,90 m de altura en muro lateral y colocar bandas antideslizantes cubriendo la totalidad del ancho del escalón."
        },
        "item_5": {
          "causa": "Acumulación de mobiliario y expedientes en Sección Dactiloscopía reduciendo pasillos de circulación",
          "que": "Reorganizar distribución de mobiliario y despejar vías de circulación y escape",
          "como": "Retirar mobiliario en desuso, reordenar puestos y garantizar ancho mínimo de paso de 1 metro."
        },
        "item_6": {
          "causa": "Tableros eléctricos con rotura o faltante de tapas y conductores desordenados expuestos (Fotos 5 a 8)",
          "que": "Regularizar tableros eléctricos con colocación de tapas/contratapas y canalización",
          "como": "Instalar contratapas aislantes de policarbonato, canalizar cableado en canaletas ignífugas y colocar carteles de riesgo eléctrico."
        },
        "item_7": {
          "causa": "Ausencia de medición de puesta a tierra",
          "que": "Medición de resistencia de Puesta a Tierra bajo Res. SRT 900/15",
          "como": "Medir jabalinas y continuidad en tableros y masas metálicas con telurímetro calibrado por profesional matriculado."
        },
        "item_9": {
          "causa": "Matafuegos apoyados directamente sobre el piso o con acceso obstruido por mobiliario (Fotos 1 a 4)",
          "que": "Instalar extintores en soportes murales y despejar áreas de acceso",
          "como": "Fijar soportes murales a 1,40 m de altura y señalizar con chapas baliza reflectantes IRAM."
        },
        "item_11": {
          "causa": "Extintor de agua a presión en archivo subsuelo ubicado junto a instalaciones eléctricas (riesgo grave de electrocución)",
          "que": "Reemplazar extintor de agua por extintor de polvo químico ABC o agente limpio (Haloclean)",
          "como": "Retirar extintor de agua e instalar extintor de PQS ABC o agente limpio apto para fuego clase C eléctrico."
        },
        "item_18": {
          "causa": "Falta cálculo de carga de fuego",
          "que": "Elaborar Estudio Técnico de Carga de Fuego",
          "como": "Relevar carga combustible de salas de archivo, museo y oficinas conforme Dec. 351/79 Anexo VII."
        },
        "item_20": {
          "causa": "Muestra de agua tomada en cocina de Antecedentes pendiente de análisis",
          "que": "Obtener protocolo de potabilidad de agua",
          "como": "Completar análisis físico-químico y bacteriológico por laboratorio según Ley 19.587 Cap. 8."
        },
        "item_26": {
          "causa": "Puestos con pantallas y atención al público sin estudio ergonómico",
          "que": "Implementar Programa de Ergonomía Integrado Res. SRT 886/15",
          "como": "Evaluar factores de riesgo por postura sedente y pantallas de visualización de datos."
        },
        "item_29": {
          "causa": "Plan de evacuación no formalizado ni adaptado a la obra en ejecución",
          "que": "Confeccionar Plan de Emergencias y Evacuación contemplando interferencia de obra",
          "como": "Establecer vías de escape seguras delimitadas de la zona de obra y designar roles de brigada."
        }
      },
