      "planEdits": {
        "item_3": {
          "causa": "Acumulación de agua sobre el piso en sector de almacenamiento transitorio de residuos (riesgo de resbalones y caídas)",
          "que": "Acondicionar drenaje y mantener sector de residuos permanentemente limpio y seco",
          "como": "Reparar rejilla o pendiente de desagüe, implementar pautas de secado y colocar cartel de piso mojado en limpiezas."
        },
        "item_6": {
          "causa": "Tableros eléctricos carecen de señalización de 'Riesgo Eléctrico' y falta identificar circuitos (Fotos 9 y 10)",
          "que": "Colocar cartelería normalizada de Riesgo Eléctrico e identificar circuitos",
          "como": "Fijar etiquetas de advertencia IRAM en puertas de gabinetes y rotular cada llave termomagnética con su circuito."
        },
        "item_7": {
          "causa": "Falta medición de PAT y continuidad de masas",
          "que": "Medición de resistencia de Puesta a Tierra bajo Res. SRT 900/15",
          "como": "Medir jabalina y tableros con telurímetro calibrado por profesional matriculado."
        },
        "item_20": {
          "causa": "Muestra de agua tomada pendiente de resultados analíticos",
          "que": "Obtener protocolo de análisis bromatológico de agua de consumo",
          "como": "Verificar calidad físico-química y bacteriológica bajo Ley 19.587 Cap. 8."
        },
        "item_26": {
          "causa": "Puestos informáticos y de oficina sin estudio ergonómico",
          "que": "Implementar Programa de Ergonomía Integrado Res. SRT 886/15",
          "como": "Evaluar condiciones posturales y disposición de mobiliario conforme a normativa SRT."
        },
        "item_30": {
          "causa": "Simulacro pendiente de realización para poner en práctica el plan existente",
          "que": "Programar y realizar simulacro de evacuación anual",
          "como": "Ejecutar ejercicio práctico con personal de oficinas y asistentes de cursos en auditorio."
        }
      },
