      "planEdits": {
        "item_3": {
          "causa": "Escalera de acceso a depósito de último nivel carece de bandas antideslizantes",
          "que": "Colocar bandas antideslizantes de alta adherencia en escalones de depósito",
          "como": "Instalar cintas antideslizantes autoadhesivas de grano grueso en borde de peldaños."
        },
        "item_5": {
          "causa": "Manipulación de metacrilato de metilo (MMA) en taller dental con emanación de vapores orgánicos y garrafas en cocina 2° piso",
          "que": "Evaluar exposición ocupacional a MMA, optimizar extracción localizada y reubicar garrafas de gas",
          "como": "Efectuar medición ambiental de concentración de vapores de MMA, revisar caudal de campana extractora y trasladar garrafas a gabinete exterior ventilado con sujeción."
        },
        "item_6": {
          "causa": "Tableros eléctricos con rotura o faltante de tapas de protección (Foto 1); cables sueltos en taller dental",
          "que": "Reemplazo de tapas rotas en tableros y canalización de cableado de equipos dentales",
          "como": "Instalar contratapas aislantes completas y canalizar cableados mediante cablecanal plástico ignífugo."
        },
        "item_7": {
          "causa": "Falta medición de PAT y continuidad de masas",
          "que": "Medición de Puesta a Tierra según Res. SRT 900/15",
          "como": "Medir jabalinas y continuidad en tableros y equipos médicos/odontológicos con telurímetro calibrado."
        },
        "item_18": {
          "causa": "Falta estudio de carga de fuego",
          "que": "Elaborar Estudio Técnico de Carga de Fuego conforme Dec. 351/79 Anexo VII",
          "como": "Relevar carga combustible de consultorios, archivo, depósitos y laboratorio dental."
        },
        "item_20": {
          "causa": "Muestra de agua tomada en cocina de 2° piso pendiente de análisis",
          "que": "Obtener protocolo bromatológico de agua de red y bidones",
          "como": "Verificar potabilidad física, química y bacteriológica bajo Ley 19.587 Cap. 8."
        },
        "item_26": {
          "causa": "Puestos de odontología, laboratorio dental y administración sin estudio ergonómico",
          "que": "Implementar Programa de Ergonomía Integrado Res. SRT 886/15",
          "como": "Evaluar bipedestación y posturas forzadas en odontólogos, mecánicos dentales y puestos con pantallas."
        },
        "item_28": {
          "causa": "Falta provisión de EPP específicos para MMA y planillas firmadas Res. SRT 299/11",
          "que": "Dotar de EPP específicos según HDS de resinas acrílicas e implementar registros de entrega",
          "como": "Proveer guantes de nitrilo específicos para químicos, protección respiratoria con filtro para vapores orgánicos y gafas de seguridad con protección lateral a mecánicos dentales."
        },
        "item_29": {
          "causa": "Plan de evacuación no formalizado ni difundido",
          "que": "Confeccionar y difundir Plan de Evacuación del centro asistencial",
          "como": "Establecer roles ante emergencias considerando la presencia de pacientes y personal de guardia."
        },
        "item_30": {
          "causa": "Simulacro no realizado",
          "que": "Programar y realizar simulacro de evacuación",
          "como": "Ejecutar ejercicio práctico en Marzo 2027 evaluando tiempos de desalojo."
        }
      },
