      "planEdits": {
        "item_1": {
          "causa": "Inexistencia de servicio de medicina del trabajo documentado y seguimiento de salud laboral",
          "que": "Gestionar cobertura de medicina laboral y cronograma de exámenes periódicos",
          "como": "Articular con Sanidad Policial asignación de horas médicas conforme a dotación y confección de nómina de personal expuesto."
        },
        "item_3": {
          "causa": "Escalera de madera hacia entrepiso en Montada y Canes inestable, sin pasamanos lateral y sin antideslizantes (Foto 18); humedad y revoques desprendidos en Comisaría 3ra; fisuras en cielorraso de Bomberos",
          "que": "Reacondicionamiento estructural de escalera y mantenimiento edilicio correctivo",
          "como": "Afirmar estructura de escalera de madera, instalar pasamanos en ambos laterales y bandas antideslizantes; reparar cielorrasos y revoques exteriores afectados por humedad."
        },
        "item_4": {
          "causa": "Falta de mediciones objetivas de iluminación por puesto según protocolo SRT",
          "que": "Efectuar estudio de niveles de iluminación según Res. SRT 84/12",
          "como": "Medición con luxómetro calibrado en oficinas de Comisaría 3ra, pañol de Bomberos, caballerizas y áreas de entrenamiento policial."
        },
        "item_5": {
          "causa": "Montada y Canes: acumulación de bolsas con insumos y materiales sobre el piso en depósitos (Fotos 10 y 11)",
          "que": "Implementar ordenamiento y estiba en depósitos de insumos y monturas",
          "como": "Instalar estanterías metálicas elevadas, despejar pasillos de circulación y clasificar elementos ecuestres y veterinarios."
        },
        "item_6": {
          "causa": "Tableros eléctricos en Bomberos sin tapas de protección y conductores accesibles con riesgo de contacto (Fotos 12 y 13)",
          "que": "Adecuación y cierre reglamentario de tableros eléctricos",
          "como": "Instalar contratapas y puertas en gabinetes, peinar cableados expuestos y colocar señalética de 'Riesgo Eléctrico'."
        },
        "item_7": {
          "causa": "Ausencia de medición de PAT y verificación de continuidad bajo normativa oficial",
          "que": "Medición de Puesta a Tierra y continuidad de masas según Res. SRT 900/15",
          "como": "Medición con telurímetro calibrado en jabalinas y masas metálicas de las tres dependencias por profesional matriculado."
        },
        "item_8": {
          "causa": "Inexistencia de certificado de aptitud eléctrica emitido por profesional electricista",
          "que": "Obtener Certificado de Aptitud de Instalación Eléctrica",
          "como": "Revisión técnica general de tableros y circuitos y certificación formal ante COPMMOTER/CIEER."
        },
        "item_9": {
          "causa": "División Montada y Canes: ausencia total de extintores portátiles en sus sectores y caballerizas",
          "que": "Dotar a la División Montada y Canes de extintores portátiles reglamentarios",
          "como": "Proveer e instalar extintores triclase ABC de 5 kg y 10 kg con soportes murales y chapas baliza IRAM en boxes, corrales y oficinas."
        },
        "item_10": {
          "causa": "Dotación general de extintores no calculada técnicamente según carga de fuego",
          "que": "Verificar y adecuar la dotación de extintores según estudio de carga de fuego",
          "como": "Ajustar unidades extintoras conforme a la carga combustible de galpones, cocheras y dependencias administrativas."
        },
        "item_14": {
          "causa": "Falta de montaje y señalización de extintores en sectores de Montada y Canes",
          "que": "Montaje reglamentario de extintores con soporte mural y chapa baliza",
          "como": "Fijar extintores a altura reglamentaria (máx. 1,50 m) y colocar balizas rojo y blanco reflectantes IRAM."
        },
        "item_17": {
          "causa": "Falta de señalética fotoluminiscente de salidas y vías de escape en dependencias",
          "que": "Instalar señalización de emergencia y medios de escape",
          "como": "Colocar carteles fotoluminiscentes de salidas de emergencia y flechas direccionales en pasillos y accesos comunes."
        },
        "item_18": {
          "causa": "Ausencia de cálculo de carga de fuego por sector según Dec. 351/79 Anexo VII",
          "que": "Elaborar Estudio Técnico de Carga de Fuego",
          "como": "Relevamiento de carga combustible en pañoles, depósitos de forraje, cocheras de autobombas y oficinas."
        },
        "item_20": {
          "causa": "Toma de muestra en canilla de cocina Comisaría 3ra pendiente de resultados analíticos de laboratorio",
          "que": "Completar análisis bacteriológico y fisicoquímico del agua de consumo",
          "como": "Obtener informe de ensayo bromatológico de laboratorio y verificar potabilidad según Ley 19.587 Cap. 8."
        },
        "item_21": {
          "causa": "Sectores con motobombas, generadores y sirenas sin evaluación sonora",
          "que": "Efectuar medición de Ruido Laboral según Res. SRT 85/12",
          "como": "Medición con decibelímetro integrador clase 2 en garaje de Bomberos y talleres operativos."
        },
        "item_26": {
          "causa": "Puestos operativos, administrativos y de cuidado animal sin evaluación ergonómica",
          "que": "Implementar Programa de Ergonomía Integrado Res. SRT 886/15",
          "como": "Completar planillas de identificación inicial para levantamiento de cargas, posturas y tareas administrativas."
        },
        "item_27": {
          "causa": "Inexistencia de libro o registro documentado de mantenimiento preventivo y correctivo de maquinarias y vehículos",
          "que": "Implementar programa documentado de mantenimiento preventivo y correctivo con registro",
          "como": "Confeccionar registros periódicos de inspección para motobombas, motosierras, equipos hidráulicos y vehículos de emergencia."
        },
        "item_28": {
          "causa": "Falta de registros individuales actualizados de entrega de EPP bajo Res. SRT 299/11",
          "que": "Implementar planillas oficiales de entrega de EPP con firma de recepción",
          "como": "Confeccionar constancias individuales de entrega de trajes estructurales, cascos, botas y guantes para todo el personal."
        },
        "item_29": {
          "causa": "Plan de evacuación y asignación de roles de emergencia no formalizado en el predio",
          "que": "Confeccionar Plan de Autoprotección y Evacuación",
          "como": "Elaborar planos de escape, definir roles operativos y procedimientos coordinados entre Comisaría, Bomberos y Montada."
        },
        "item_30": {
          "causa": "Nunca se realizó simulacro de evacuación conjunto en las tres dependencias",
          "que": "Programar y realizar simulacro de incendio y evacuación general",
          "como": "Ejecutar ejercicio práctico con toma de tiempos y elaboración de informe técnico post-simulacro."
        },
        "item_31": {
          "causa": "Brigada de emergencia no conformada formalmente en dependencias administrativas y montada",
          "que": "Conformar y capacitar brigada de emergencia interdisciplinaria",
          "como": "Designar y entrenar brigadistas de las distintas dependencias en roles de alarma, evacuación y primeros auxilios."
        },
        "item_33": {
          "causa": "RGRL pendiente de presentación formal ante la ART",
          "que": "Confeccionar y presentar RGRL actualizado ante IAPSER ART",
          "como": "Remitir el relevamiento con constancia de recepción de la aseguradora."
        },
        "item_34": {
          "causa": "RAR no confeccionado respecto a agentes de riesgo del establecimiento",
          "que": "Confeccionar y remitir el RAR ante IAPSER ART",
          "como": "Declarar nómina de personal expuesto según mediciones de ruido y ergonomía."
        },
        "item_36": {
          "causa": "Falta de exámenes periódicos de salud laboral coordinados",
          "que": "Coordinar exámenes periódicos con ART y Sanidad Policial",
          "como": "Articular la nómina de trabajadores para realización de estudios médicos periódicos."
        }
      },
