      "planEdits": {
        "item_5": {
          "causa": "Cilindro de GLP exterior con corrosión y sin fijación; garrafa de GLP instalada en interior de cocina de Alcaldía (Foto 5)",
          "que": "Adecuación de cilindro exterior con sujeción y reubicación de garrafa al exterior",
          "como": "Sujetar cilindro exterior con cadena y proteger válvula; trasladar garrafa de cocina de alcaldía a gabinete exterior ventilado con cañería rígida reglamentaria."
        },
        "item_6": {
          "causa": "Tableros eléctricos de Comisaría 5ta y Alcaldía no disponen de interruptor diferencial y tienen cables sin canalizar (Fotos 3 y 4)",
          "que": "Instalar interruptores diferenciales (disyuntores) y canalizar conductores en ambos tableros",
          "como": "Instalar disyuntor de 30 mA en tablero principal y secundario, peinar cableado, colocar tapas y señalizar con carteles de riesgo eléctrico."
        },
        "item_7": {
          "causa": "Ausencia de medición de puesta a tierra",
          "que": "Medición de resistencia de Puesta a Tierra bajo Res. SRT 900/15",
          "como": "Medir jabalinas y continuidad en tableros y masas metálicas con telurímetro con certificado de calibración."
        },
        "item_9": {
          "causa": "Extintor de Comisaría 5ta vencido (Foto 1) y extintor de Alcaldía en el suelo sin soporte (Foto 2)",
          "que": "Enviar a recarga extintor vencido e instalar soporte mural para extintor de Alcaldía",
          "como": "Gestionar recarga inmediata con empresa habilitada y amurar soporte a 1,40 m con chapa baliza reflectante en Alcaldía."
        },
        "item_18": {
          "causa": "Falta estudio de carga de fuego",
          "que": "Elaborar Estudio Técnico de Carga de Fuego conforme Dec. 351/79 Anexo VII",
          "como": "Relevar carga combustible de dependencias policiales y celdas."
        },
        "item_20": {
          "causa": "Muestra tomada en cocina de Comisaría 5ta pendiente de análisis",
          "que": "Obtener protocolo de potabilidad de agua de red",
          "como": "Completar análisis bromatológico en laboratorio según Ley 19.587 Cap. 8."
        },
        "item_21": {
          "causa": "Sin estudio de niveles de ruido",
          "que": "Realizar medición de ruido laboral bajo Res. SRT 85/12",
          "como": "Medición con decibelímetro en sectores de guardia y cocina."
        },
        "item_26": {
          "causa": "Puestos de trabajo sin evaluación ergonómica",
          "que": "Implementar Programa de Ergonomía Integrado Res. SRT 886/15",
          "como": "Evaluar puestos de guardia, celdas y oficinas administrativas."
        },
        "item_29": {
          "causa": "Plan de evacuación no formalizado",
          "que": "Confeccionar Plan de Emergencias y Evacuación considerando sector de detenidos",
          "como": "Definir procedimientos específicos y llaves de emergencia para traslado seguro ante siniestro."
        }
      },
