      "planEdits": {
        "item_3": {
          "causa": "Abertura sin baranda de protección hacia el taller en sector de tapicería y desnivel en acceso",
          "que": "Instalar barandas perimetrales en sector tapicería y nivelar acceso",
          "como": "Colocar baranda metálica reglamentaria con zócalo de contención en la abertura hacia el taller y reparar rampa/desnivel de ingreso."
        },
        "item_4": {
          "causa": "Nivel de iluminación insuficiente en áreas operativas del taller mecánico (Foto 18)",
          "que": "Adecuar luminarias y realizar estudio de iluminación bajo Res. SRT 84/12",
          "como": "Incorporar artefactos LED de alta eficiencia en bancos de trabajo y medir con luxómetro."
        },
        "item_5": {
          "causa": "Tambores con lubricantes y químicos almacenados sin cubetos de contención secundaria (Fotos 13 y 14)",
          "que": "Instalar bateas de retención secundaria y señalizar sector de sustancias peligrosas",
          "como": "Colocar cubetos colectores bajo tambores, rotular conforme a SGA y disponer kit para derrames."
        },
        "item_6": {
          "causa": "Tableros eléctricos de taller con partes energizadas expuestas, falta de tapas y cableado desordenado (Fotos 15, 16 y 17)",
          "que": "Reparar tableros de taller, colocar tapas/contratapas aislantes y canalizar cableado",
          "como": "Instalar contratapas protectoras, peinar conductores, rotular térmicas y colocar cartelería de advertencia."
        },
        "item_7": {
          "causa": "Falta medición de PAT y verificación de continuidad",
          "que": "Medición de resistencia de Puesta a Tierra según Res. SRT 900/15",
          "como": "Medir jabalinas y continuidad en tableros y masas de máquinas elevadoras con telurímetro calibrado."
        },
        "item_9": {
          "causa": "Matafuegos obstruidos por herramientas/repuestos en taller y señalización deficiente (Fotos 10 y 11)",
          "que": "Despejar accesos a matafuegos y colocar señalización reglamentaria",
          "como": "Mantener libres de obstáculos los extintores, colocar chapas baliza IRAM a 1,50 m y demarcar franjas amarillas en el piso."
        },
        "item_18": {
          "causa": "Inexistencia de cálculo de carga de fuego",
          "que": "Elaborar Estudio Técnico de Carga de Fuego",
          "como": "Relevar carga combustible de talleres mecánicos, tapicería, repuestos y oficinas administrativas."
        },
        "item_20": {
          "causa": "Muestra de agua tomada pendiente de análisis",
          "que": "Obtener protocolo de análisis bromatológico de agua",
          "como": "Verificar aptitud físico-química y bacteriológica bajo Ley 19.587 Cap. 8."
        },
        "item_26": {
          "causa": "Puestos de taller, tapicería y comisaría sin estudio ergonómico",
          "que": "Implementar Programa de Ergonomía Integrado Res. SRT 886/15",
          "como": "Evaluar riesgos por manipulación manual de autopartes, posturas bajo fosa/elevador y tareas administrativas."
        },
        "item_27": {
          "causa": "Elevadores vehiculares y aparejo manual sin libro de inspección periódica",
          "que": "Implementar programa de mantenimiento preventivo e inspección de equipos de izaje",
          "como": "Verificar cables, cadenas, trabas de seguridad y señalizar carga máxima admisible en elevadores."
        },
        "item_28": {
          "causa": "Falta provisión completa de EPP y planillas firmadas Res. SRT 299/11",
          "que": "Proveer EPP completos y registrar entrega oficial por trabajador",
          "como": "Suministrar calzado de seguridad con puntera, protección ocular, guantes de nitrilo y protección auditiva."
        },
        "item_29": {
          "causa": "Plan de evacuación no formalizado",
          "que": "Confeccionar Plan de Autoprotección y Evacuación",
          "como": "Definir vías de escape, puntos de reunión y roles de emergencia para comisaría y talleres."
        }
      },
